import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Radio","description":"","frontmatter":{},"headers":[],"relativePath":"components/radio.md","filePath":"components/radio.md"}'),i={name:"components/radio.md"};function r(n,e,s,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="radio" tabindex="-1">Radio <a class="header-anchor" href="#radio" aria-label="Permalink to &quot;Radio&quot;">​</a></h1><p>Radio is one choice of a group in which one is chosen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it on its own when the choices do not stand in one list; a group in one list is a <a href="./radio-group">RadioGroup</a>. The radios of one group share <code>name</code>, and <code>group</code> holds the chosen value. A radio can carry a second line that describes the choice, and a note under the label (a snippet).</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>required</td><td>The value of this choice</td></tr><tr><td><code>label</code></td><td>required</td><td>The text of the choice</td></tr><tr><td><code>name</code></td><td>required</td><td>The name shared by the group</td></tr><tr><td><code>group</code></td><td></td><td>The chosen value (bindable)</td></tr><tr><td><code>description</code></td><td></td><td>A second line that describes the choice</td></tr><tr><td><code>note</code></td><td></td><td>A note under the label, in the column of the text (a snippet)</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Cannot be chosen</td></tr><tr><td><code>id</code></td><td></td><td>The id of the input</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the value when it is chosen</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The first line is as high as a small button, and the whole control is pressed. The circle is a native radio in the square of an icon; chosen, its line and a dot inside take the solid color. The text is gap-sm from the circle, one line, trimmed to its ink. A description is a caption in the column of the text, trimmed to its ink, gap-xs below the first line, and so is a note, gap-xs below what is above it; pad-sm lies below the last of them, so that a description is nearer its own label than the label of the next radio. In a <a href="./radio-group">RadioGroup</a> the radios stay stacked with gap 0. Disabled, the text and an empty circle are dimmed; a chosen one takes the solid-disabled color for its line and its text color for the dot, not dimmed.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/radio/" title="Radio" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/radio/" target="_blank" rel="noopener">Radio</a></figcaption></figure>',10)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
